import{_ as r,a0 as d,w as l,s as p,I as n,x as s,a1 as e,A as i,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"在 WSL 上忘记了 Linux 密码？下面是如何轻松重设的方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 WSL 上忘记了 Linux 密码？下面是如何轻松重设的方法 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 WSL 上忘记了 Linux 密码？下面是如何轻松重设的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 WSL 上忘记了 Linux 密码？下面是如何轻松重设的方法 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210628 Forgot Linux Password on WSL- Here-s How to Reset it Easily","title":"在 WSL 上忘记了 Linux 密码？下面是如何轻松重设的方法","tag":"202107","desc":""},"relativePath":"202107/20210628 Forgot Linux Password on WSL- Here-s How to Reset it Easily.md","filePath":"[post].md"}'),u={name:"202107/20210628 Forgot Linux Password on WSL- Here-s How to Reset it Easily.md"};function m(f,t,g,w,h,b){const o=d("Link");return l(),p("div",null,[t[24]||(t[24]=n("h1",{id:"在-wsl-上忘记了-linux-密码-下面是如何轻松重设的方法",tabindex:"-1"},[s("在 WSL 上忘记了 Linux 密码？下面是如何轻松重设的方法 "),n("a",{class:"header-anchor",href:"#在-wsl-上忘记了-linux-密码-下面是如何轻松重设的方法","aria-label":"Permalink to “在 WSL 上忘记了 Linux 密码？下面是如何轻松重设的方法”"},"​")],-1)),t[25]||(t[25]=n("p",null,"对于那些想从舒适的 Windows 中享受 Linux 命令行的人来说，WSL（Windows Subsystem for Linux） 是一个方便的工具。",-1)),n("p",null,[t[1]||(t[1]=s("当你 ",-1)),e(o,{href:"https://itsfoss.com/install-bash-on-windows/"},{default:i(()=>[...t[0]||(t[0]=[s("在 Windows 上使用 WSL 安装 Linux",-1)])]),_:1}),t[2]||(t[2]=s(" 时，会要求你创建一个用户名和密码。当你在 WSL 上启动 Linux 时，这个用户会自动登录。",-1))]),t[26]||(t[26]=a('<p>现在的问题是，如果你有一段时间没有使用它，你可能会忘记 WSL 的账户密码。而如果你要使用 <code>sudo</code> 的命令，这将成为一个问题，因为这里你需要输入密码。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/06/reset-wsl-password.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>不要担心。你可以很容易地重置它。</p><h3 id="在-ubuntu-或任何其他-linux-发行版上重置遗忘的-wsl-密码" tabindex="-1">在 Ubuntu 或任何其他 Linux 发行版上重置遗忘的 WSL 密码 <a class="header-anchor" href="#在-ubuntu-或任何其他-linux-发行版上重置遗忘的-wsl-密码" aria-label="Permalink to “在 Ubuntu 或任何其他 Linux 发行版上重置遗忘的 WSL 密码”">​</a></h3><p>要在 WSL 中重设 Linux 密码，你需要：</p><ul><li>将默认用户切换为 <code>root</code></li><li>重置普通用户的密码</li><li>将默认用户切换回普通用户</li></ul><p>让我向你展示详细的步骤和截图。</p><h4 id="步骤-1-将默认用户切换为-root" tabindex="-1">步骤 1：将默认用户切换为 root <a class="header-anchor" href="#步骤-1-将默认用户切换为-root" aria-label="Permalink to “步骤 1：将默认用户切换为 root”">​</a></h4><p>记下你的普通/常规用户名将是明智之举。如你所见，我的普通帐户的用户名是 <code>abhishek</code>。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/06/username-wsl.png?resize=800%2C296&amp;ssl=1" alt="Note down the account username"></p><p>WSL 中的 <code>root</code> 用户是无锁的，没有设置密码。这意味着你可以切换到 <code>root</code> 用户，然后利用 <code>root</code> 的能力来重置密码。</p><p>由于你不记得帐户密码，切换到 <code>root</code> 用户是通过改变你的 Linux WSL 应用的配置，使其默认使用 <code>root</code> 用户来完成。</p><p>这是通过 Windows 命令提示符完成的，你需要知道你的 Linux 发行版需要运行哪个命令。</p>',13)),n("p",null,[t[4]||(t[4]=s("这个信息通常在 ",-1)),e(o,{href:"https://www.microsoft.com/en-us/store/apps/windows"},{default:i(()=>[...t[3]||(t[3]=[s("Windows 商店",-1)])]),_:1}),t[5]||(t[5]=s(" 中的发行版应用的描述中提供。这是你首次下载发行版的地方。",-1))]),t[27]||(t[27]=a('<p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/wsl-distro-command.png?resize=800%2C602&amp;ssl=1" alt="Know the command to run for your distribution app"></p><p>从 Windows 菜单中，启动命令提示符：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/start-cmd-windows.jpg?resize=800%2C500&amp;ssl=1" alt="Start Command Prompt"></p><p>在这里，以这种方式使用你的发行版的命令。如果你使用的是 Windows 商店中的 Ubuntu 应用，那么该命令将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ubuntu config --default-user root</span></span></code></pre></div><p>截图中，我正在使用 Windows 商店中的 Ubuntu 20.04 应用。所以，我使用了 ubuntu2004 命令。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/06/wsl-set-root-as-default.png?resize=800%2C288&amp;ssl=1" alt="Set root as default user in Linux app’s configuration"></p><p>为了减少你的麻烦，我在这个表格中列出了一些发行版和它们各自的命令：</p><div class="table-wrap"><table><thead><tr><th>发行版应用</th><th>Windows 命令</th></tr></thead><tbody><tr><td>Ubuntu</td><td><code>ubuntu config –default-user root</code></td></tr><tr><td>Ubuntu 20.04</td><td><code>ubuntu2004 config –default-user root</code></td></tr><tr><td>Ubuntu 18.04</td><td><code>ubuntu1804 config –default-user root</code></td></tr><tr><td>Debian</td><td><code>debian config –default-user root</code></td></tr><tr><td>Kali Linux</td><td><code>kali config –default-user root</code></td></tr></tbody></table></div><h4 id="步骤-2-重设帐户密码" tabindex="-1">步骤 2：重设帐户密码 <a class="header-anchor" href="#步骤-2-重设帐户密码" aria-label="Permalink to “步骤 2：重设帐户密码”">​</a></h4><p>现在，如果你启动 Linux 发行程序，你应该以 <code>root</code> 身份登录。你可以重新设置普通用户帐户的密码。</p><p>你还记得 WSL 中的用户名吗？（LCTT 译注：请使用你的“用户名”替换下列命令中的 <code>username</code>）如果没有，你可以随时检查 <code>/home</code> 目录的内容。当你有了用户名后，使用这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd username</span></span></code></pre></div><p>它将要求你输入一个新的密码。<strong>当你输入时，屏幕上将不会显示任何内容。这很正常。只要输入新的密码，然后点击回车就可以了。</strong>你必须重新输入新的密码来确认，当你输入密码时，屏幕上也不会显示任何东西。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/06/resetting-wsl-password.png?resize=800%2C366&amp;ssl=1" alt="Reset the password for the regular user"></p><p>恭喜你。用户账户的密码已经被重置。但你还没有完成。默认用户仍然是 <code>root</code>。你应该把它改回你的普通用户帐户，否则它将一直以 <code>root</code> 用户的身份登录。</p><h4 id="步骤-3-再次将普通用户设置为默认用户" tabindex="-1">步骤 3：再次将普通用户设置为默认用户 <a class="header-anchor" href="#步骤-3-再次将普通用户设置为默认用户" aria-label="Permalink to “步骤 3：再次将普通用户设置为默认用户”">​</a></h4>',17)),n("p",null,[t[7]||(t[7]=s("你需要你在上一步中用 ",-1)),e(o,{href:"https://linuxhandbook.com/passwd-command/"},{default:i(()=>[...t[6]||(t[6]=[s("passwd 命令",-1)])]),_:1}),t[8]||(t[8]=s(" 使用的普通帐户用户名。",-1))]),t[28]||(t[28]=a('<p>再次启动 Windows 命令提示符。<strong>使用你的发行版命令</strong>，方式与第 1 步中类似。然而，这一次，用普通用户代替 <code>root</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ubuntu config --default-user username</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/set-regular-user-as-default-wsl.png?resize=800%2C288&amp;ssl=1" alt="Set regular user as default user"></p><p>现在，当你在 WSL 中启动你的 Linux 发行版时，你将以普通用户的身份登录。你已经重新设置了密码，可以用它来运行 <code>sudo</code> 命令。</p><p>如果你将来再次忘记了密码，你知道重置密码的步骤。</p><h3 id="如果重设-wsl-密码如此简单-这难道不是一种安全风险吗" tabindex="-1">如果重设 WSL 密码如此简单，这难道不是一种安全风险吗？ <a class="header-anchor" href="#如果重设-wsl-密码如此简单-这难道不是一种安全风险吗" aria-label="Permalink to “如果重设 WSL 密码如此简单，这难道不是一种安全风险吗？”">​</a></h3><p>并非如此。你需要有对计算机的物理访问权以及对 Windows 帐户的访问权。如果有人已经有这么多的访问权，他/她可以做很多事情，而不仅仅是改变 WSL 中的 Linux 密码。</p><h3 id="你是否能够重新设置-wsl-密码" tabindex="-1">你是否能够重新设置 WSL 密码？ <a class="header-anchor" href="#你是否能够重新设置-wsl-密码" aria-label="Permalink to “你是否能够重新设置 WSL 密码？”">​</a></h3><p>我给了你命令并解释了步骤。我希望这对你有帮助，并能够在 WSL 中重置你的 Linux 发行版的密码。</p><p>如果你仍然遇到问题，或者你对这个话题有疑问，请随时在评论区提问。</p><hr>',11)),n("p",null,[t[10]||(t[10]=s("via: ",-1)),e(o,{href:"https://itsfoss.com/reset-linux-password-wsl/"},{default:i(()=>[...t[9]||(t[9]=[s("https://itsfoss.com/reset-linux-password-wsl/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=s("作者：",-1)),e(o,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...t[11]||(t[11]=[s("Abhishek Prakash",-1)])]),_:1}),t[16]||(t[16]=s(" 选题：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[12]||(t[12]=[s("lujun9972",-1)])]),_:1}),t[17]||(t[17]=s(" 译者：",-1)),e(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[13]||(t[13]=[s("geekpi",-1)])]),_:1}),t[18]||(t[18]=s(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[14]||(t[14]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=s("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[s("LCTT",-1)])]),_:1}),t[22]||(t[22]=s(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[s("Linux中国",-1)])]),_:1}),t[23]||(t[23]=s(" 荣誉推出",-1))])])}const c=r(u,[["render",m]]);export{k as __pageData,c as default};
